UPDATE notification_delivery_outbox
SET status='RETRY',attempts=attempts+1,next_attempt_at=#{nextAttemptAt},last_error=#{error}
WHERE id=#{id} AND status IN ('NEW','RETRY')

UPDATE notification_delivery_outbox
SET status='FALLBACK',attempts=attempts+1,processed_at=CURRENT_TIMESTAMP,last_error=#{error}
WHERE id=#{id} AND status IN ('NEW','RETRY')

UPDATE notification_delivery_outbox
SET status='DEAD',attempts=attempts+1,processed_at=CURRENT_TIMESTAMP,last_error=#{error}
WHERE id=#{id} AND status IN ('NEW','RETRY')
